/** A Video-on-Demand asset uploaded by the tenant. VOD assets can be played back using the playbackId in playback URLs. */
export type VodAssetInNodeDefaultFieldsFragment = { /** Global unique identifier for Relay compatibility. */
id: string, /** Internal hash used for playback URL resolution. */
artifactHash: string, /** Public playback identifier for generating playback URLs. */
playbackId: string, /** Registry origin kind. Null/user_upload for ordinary uploads; dvr_chapter for finalized DVR chapters. */
originType: string | null, /** Origin entity id, such as DVR chapter_id when originType=dvr_chapter. */
originId: string | null, /** Optional description of the asset content. */
description: string | null, /** Original filename when uploaded. */
filename: string | null, /** Current S3 sync state (pending, in_progress, synced, failed, lost_local). */
syncStatus: string | null, /** Present full local node copy (origin or cache): true when at least one node holds a complete local copy, false when none remain (playback via Helmsman's read-through relay from S3). Null when the placement overlay (Periscope) is unavailable — unknown, not 'no local copy'. Durable S3-only state is derived by consumers as isSynced && hasLocalCopy == false. */
hasLocalCopy: boolean | null, /** File size in bytes (available after validation). */
sizeBytes: number | null, /** Video duration in milliseconds. */
durationMs: number | null, /** Video resolution (e.g., '1920x1080'). */
resolution: string | null, /** Video codec (h264, h265, vp9, av1). */
videoCodec: string | null, /** Audio codec (aac, opus). */
audioCodec: string | null, /** Average bitrate in kbps. */
bitrateKbps: number | null, /** When the asset was created/uploaded. */
createdAt: string, /** Optional expiration time for auto-deletion. */
expiresAt: string | null, /** Error message if processing failed. */
errorMessage: string | null, /** Source stream UUID for stream-derived VOD artifacts such as DVR chapters. */
vodAssetStreamId: string | null, /** Optional display title for the asset. */
vodAssetTitle: string | null, /** Current processing/storage status of the asset. */
vodAssetStatus: VodAssetStatus, /** Where the asset is stored (s3, local, freezing). */
vodAssetStorageLocation: string, /** True when S3 has an authoritative copy. */
vodAssetIsSynced: boolean, /** True when the S3 copy includes the Mist .dtsh index. */
vodAssetIsFinalized: boolean, /** When the asset was last modified. */
vodAssetUpdatedAt: string, /** Playback access policy. null/PUBLIC = anyone with the playbackId can watch. */
playbackPolicy: { type: PlaybackPolicyType, /** Sites allowed to embed the content, as normalized `scheme://host[:port]` origins; `*` allows any. Empty = no restriction. A browser viewer whose Origin (or Referer) is not listed is denied. */
allowedOrigins: Array<string>, /** JWT-policy details, populated when type == JWT. */
jwt: { /** Allowed signing key IDs. Empty = any active tenant key. */
allowedKids: Array<string>, /** If set, the viewer JWT's `aud` claim must contain at least one of these. */
requiredAudience: Array<string> } | null, /** Webhook-policy details, populated when type == WEBHOOK. Secret is masked. */
webhook: { url: string, /** Outbound POST timeout in milliseconds. Capped server-side at 10000. */
timeoutMs: number, /** Always 'redacted' on read; the actual secret is fieldcrypt-encrypted at rest. */
secretMasked: string, /** Your JSON object, sent as `context` in every access request to the URL. Null when unset. */
context: unknown } | null } | null, /** Server-resolved Chandler URLs for the VOD's poster and sprite thumbnails. Null until Foghorn confirms the thumbnail upload. */
thumbnailAssets: { posterUrl: string, spriteVttUrl: string, spriteJpgUrl: string, assetKey: string } | null, /** Resolved retention horizon with the source of the decision (per-asset override → per-stream override → tenant default → tier entitlement). Null while the asset's retention_until column is unset (infinite). */
effectiveRetention: { /** Days from now until the artifact is scheduled for deletion. 0 = no auto-expire (retentionUntil is null). */
retentionDays: number, /** Scheduled deletion timestamp. Null when the artifact has no horizon (kept forever). */
retentionUntil: string | null, source: RetentionSource } | null, /** Marginal storage cost for this asset on the tenant's tier. Null when the tenant has no storage meter (self-hosted, fully tenant-private cluster). Computed from sizeBytes in GiB × the tier's price per GiB-month. */
storageCost: { perDay: number, perMonth: number, currency: string } | null };

/** A VOD asset with retention data in the window. Eligibility + stats (sessions, duration, lastSeen) come from analytics; title/playbackId are composed from the catalog by artifactHash — both may be null when the asset is uncatalogued (e.g. deleted but retention still within TTL). */
export type VodRetentionAssetDefaultFieldsFragment = { artifactHash: string, totalSessions: number, durationS: number, lastSeen: string, title: string | null, playbackId: string | null };

/** VOD retention curve for an artifact. retention(T) = points[T].reached / totalSessions (monotonic non-increasing); density(T) = points[T].secondsWatched (the "most replayed" curve). Buckets are fixed-width (bucketWidthS) along the asset timeline. These differ because a seek-to-end raises reach without adding density. */
export type VodRetentionDefaultFieldsFragment = { bucketWidthS: number, assetDurationS: number, totalSessions: number, points: Array<{ bucketIndex: number, secondsWatched: number, reached: number }> };

